		this._player = new com_tilbuci_ui_PlayerHolder(com_tilbuci_data_Global.econfig.get_player(),$bind(this,this.playerCallback));
		this._playerControls = new com_tilbuci_ui_PlayerControls(this._player,$bind(this,this.playerCallback));
		this._centertArea.addChild(this._playerControls);
		var h = com_tilbuci_data_Global.plugins.h;
		var pl_h = h;
		var pl_keys = Object.keys(h);
		var pl_length = pl_keys.length;
		var pl_current = 0;
