	,editorActions: function(name,data) {
		switch(name) {
		case "addleftbutton":
			this._leftArea.addButton(data.h["name"],data.h["callback"],data.h["top"],data.h["asset"]);
			return true;
		case "hidewindow":
			var wd = data.h["wd"];
			feathers_core_PopUpManager.removePopUp(wd);
			return true;
		case "showwindow":
			var wd = data.h["wd"];
			feathers_core_PopUpManager.addPopUp(wd,this);
			wd.redraw();
			wd.acStart();
			return true;
		default:
			return false;
		}
	}
