	,menuShow: function(name,options,variable,actions,pos,px,py) {
		this.menuHide();
		if(Object.prototype.hasOwnProperty.call(this.menus.h,name) && com_tilbuci_data_GlobalPlayer.mode != "editor") {
			this._menuCurrent = this.menus.h[name];
			if(this._menuCurrent.ok) {
				this._menusOverlay.get_graphics().clear();
				if(this._menuCurrent.bgalpha > 0) {
					this._menusOverlay.get_graphics().beginFill(Std.parseInt(StringTools.replace("#","0x",this._menuCurrent.bgcolor)),this._menuCurrent.bgalpha);
					this._menusOverlay.get_graphics().drawRect(0,0,com_tilbuci_data_GlobalPlayer.area.get_aWidth(),com_tilbuci_data_GlobalPlayer.area.get_aHeight());
					this._menusOverlay.get_graphics().endFill();
				}
				this._menusOverlay.addChild(this._menuCurrent.create(options,$bind(this,this.onMenuSelect)));
				switch(pos) {
				case "absolute":
					this._menuCurrent.set_x(px);
					this._menuCurrent.set_y(py);
					break;
				case "bottom":
					this._menuCurrent.set_x((com_tilbuci_data_GlobalPlayer.area.get_aWidth() - this._menuCurrent.get_width()) / 2);
					this._menuCurrent.set_y(com_tilbuci_data_GlobalPlayer.area.get_aHeight() - this._menuCurrent.get_height() - py);
					break;
				case "bottomleft":
					this._menuCurrent.set_x(px);
					this._menuCurrent.set_y(com_tilbuci_data_GlobalPlayer.area.get_aHeight() - this._menuCurrent.get_height() - py);
					break;
				case "bottomright":
					this._menuCurrent.set_x(com_tilbuci_data_GlobalPlayer.area.get_aWidth() - this._menuCurrent.get_width() - px);
					this._menuCurrent.set_y(com_tilbuci_data_GlobalPlayer.area.get_aHeight() - this._menuCurrent.get_height() - py);
					break;
				case "centerleft":
					this._menuCurrent.set_x(px);
					this._menuCurrent.set_y((com_tilbuci_data_GlobalPlayer.area.get_aHeight() - this._menuCurrent.get_height()) / 2);
					break;
				case "centerright":
					this._menuCurrent.set_x(com_tilbuci_data_GlobalPlayer.area.get_aWidth() - this._menuCurrent.get_width() - px);
					this._menuCurrent.set_y((com_tilbuci_data_GlobalPlayer.area.get_aHeight() - this._menuCurrent.get_height()) / 2);
					break;
				case "top":
					this._menuCurrent.set_x((com_tilbuci_data_GlobalPlayer.area.get_aWidth() - this._menuCurrent.get_width()) / 2);
					this._menuCurrent.set_y(py);
					break;
				case "topleft":
					this._menuCurrent.set_x(px);
					this._menuCurrent.set_y(py);
					break;
				case "topright":
					this._menuCurrent.set_x(com_tilbuci_data_GlobalPlayer.area.get_aWidth() - this._menuCurrent.get_width() - px);
					this._menuCurrent.set_y(py);
					break;
				default:
					this._menuCurrent.set_x((com_tilbuci_data_GlobalPlayer.area.get_aWidth() - this._menuCurrent.get_width()) / 2);
					this._menuCurrent.set_y((com_tilbuci_data_GlobalPlayer.area.get_aHeight() - this._menuCurrent.get_height()) / 2);
				}
				this._menuAction = actions;
				this._menuVariable = variable;
				this.usingMenu = true;
				return true;
			} else {
				this._menuCurrent = null;
				return false;
			}
		} else {
			this._menuCurrent = null;
			return false;
		}
	}
	,checkMenuCollision: function(obj) {
		if(this._menuCurrent != null) {
			return this._menuCurrent.checkCollision(obj);
		} else {
			return false;
		}
	}
	,checkMenuOver: function(obj) {
		if(this._menuCurrent != null) {
			if(this._menuCurrent.hitTestObject(obj)) {
				return true;
			} else {
				return false;
			}
		} else {
			return false;
		}
	}
