		if(all == null) {
			all = false;
		}
		this.menuHide();
		this.messagesHide();
		this.dflowHide();
		this.invHide();
		this.bsHide();
		this.hideForm();
		this.hideLoadingIc();
		this.removeZoom();
		this.hideQR();
