	,musicPlay: function(name) {
		if(Object.prototype.hasOwnProperty.call(this.musics.h,name)) {
			var h = this.musics.h;
			var ms_h = h;
			var ms_keys = Object.keys(h);
			var ms_length = ms_keys.length;
			var ms_current = 0;
			while(ms_current < ms_length) {
				var ms = ms_h[ms_keys[ms_current++]];
				if(ms.id == name) {
					ms.play();
				} else {
					ms.pause();
				}
			}
			return true;
		} else {
			return false;
		}
	}
