	,setAnimation: function(to) {
		switch(to) {
		case "bounce.in":
			motion_Actuate.defaultEase = motion_easing_Bounce.easeIn;
			break;
		case "bounce.inout":
			motion_Actuate.defaultEase = motion_easing_Bounce.easeInOut;
			break;
		case "bounce.out":
			motion_Actuate.defaultEase = motion_easing_Bounce.easeOut;
			break;
		case "cubic.in":
			motion_Actuate.defaultEase = motion_easing_Cubic.easeIn;
			break;
		case "cubic.inout":
			motion_Actuate.defaultEase = motion_easing_Cubic.easeInOut;
			break;
		case "cubic.out":
			motion_Actuate.defaultEase = motion_easing_Cubic.easeOut;
			break;
		case "elastic.in":
			motion_Actuate.defaultEase = motion_easing_Elastic.easeIn;
			break;
		case "elastic.inout":
			motion_Actuate.defaultEase = motion_easing_Elastic.easeInOut;
			break;
		case "elastic.out":
			motion_Actuate.defaultEase = motion_easing_Elastic.easeOut;
			break;
		case "expo.in":
			motion_Actuate.defaultEase = motion_easing_Expo.easeIn;
			break;
		case "expo.inout":
			motion_Actuate.defaultEase = motion_easing_Expo.easeInOut;
			break;
		case "expo.out":
			motion_Actuate.defaultEase = motion_easing_Expo.easeOut;
			break;
		case "linear":
			motion_Actuate.defaultEase = motion_easing_Linear.get_easeNone();
			break;
		case "quad.in":
			motion_Actuate.defaultEase = motion_easing_Quad.easeIn;
			break;
		case "quad.inout":
			motion_Actuate.defaultEase = motion_easing_Quad.easeInOut;
			break;
		case "quad.out":
			motion_Actuate.defaultEase = motion_easing_Quad.easeOut;
			break;
		case "quart.in":
			motion_Actuate.defaultEase = motion_easing_Quart.easeIn;
			break;
		case "quart.inout":
			motion_Actuate.defaultEase = motion_easing_Quart.easeInOut;
			break;
		case "quart.out":
			motion_Actuate.defaultEase = motion_easing_Quart.easeOut;
			break;
		case "quint.in":
			motion_Actuate.defaultEase = motion_easing_Quint.easeIn;
			break;
		case "quint.inout":
			motion_Actuate.defaultEase = motion_easing_Quint.easeInOut;
			break;
		case "quint.out":
			motion_Actuate.defaultEase = motion_easing_Quint.easeOut;
			break;
		case "sine.in":
			motion_Actuate.defaultEase = motion_easing_Sine.easeIn;
			break;
		case "sine.inout":
			motion_Actuate.defaultEase = motion_easing_Sine.easeInOut;
			break;
		case "sine.out":
			motion_Actuate.defaultEase = motion_easing_Sine.easeOut;
			break;
		}
	}
