	,getOverlay: function(name,below) {
		if(below == null) {
			below = false;
		}
		if(below) {
			if(!Object.prototype.hasOwnProperty.call(this._bloverlays.h,name)) {
				var this1 = this._bloverlays;
				var v = new openfl_display_Sprite();
				this1.h[name] = v;
				this._bloverlay.addChild(this._bloverlays.h[name]);
			}
			return this._bloverlays.h[name];
		} else {
			if(!Object.prototype.hasOwnProperty.call(this._overlays.h,name)) {
				var this1 = this._overlays;
				var v = new openfl_display_Sprite();
				this1.h[name] = v;
				this._overlay.addChild(this._overlays.h[name]);
			}
			return this._overlays.h[name];
		}
	}
	,removeOverlay: function(name,below) {
		if(below == null) {
			below = false;
		}
		if(below) {
			if(Object.prototype.hasOwnProperty.call(this._bloverlays.h,name)) {
				this._bloverlay.removeChild(this._bloverlays.h[name]);
				this._bloverlays.h[name].removeChildren();
				this._bloverlays.h[name].get_graphics().clear();
				var _this = this._bloverlays;
				if(Object.prototype.hasOwnProperty.call(_this.h,name)) {
					delete(_this.h[name]);
				}
				return true;
			} else {
				return false;
			}
		} else if(Object.prototype.hasOwnProperty.call(this._overlays.h,name)) {
			this._overlay.removeChild(this._overlays.h[name]);
			this._overlays.h[name].removeChildren();
			this._overlays.h[name].get_graphics().clear();
			var _this = this._overlays;
			if(Object.prototype.hasOwnProperty.call(_this.h,name)) {
				delete(_this.h[name]);
			}
			return true;
		} else {
			return false;
		}
	}
