	,kill: function() {
		this.removeEventListener("mouseUp",$bind(this,this.onMouseUp));
		this._bgarea.removeChildren();
		this._bgarea.get_graphics().clear();
		this._bgarea = null;
		this._player = null;
		this.removeChildren();
		this._holder.removeChildren();
		this._holder.set_mask(null);
		this._holder = null;
		this._bg.get_graphics().clear();
		this._bg = null;
		this._mask.get_graphics().clear();
		this._mask = null;
		this._scene.removeChildren();
		this._scene = null;
		var h = this._overlays.h;
		var o_h = h;
		var o_keys = Object.keys(h);
		var o_length = o_keys.length;
		var o_current = 0;
		while(o_current < o_length) {
			var o = o_keys[o_current++];
			this.removeOverlay(o);
		}
		this._overlays = null;
		this._overlay.removeChildren();
		this._overlay = null;
		var h = this._bloverlays.h;
		var o_h = h;
		var o_keys = Object.keys(h);
		var o_length = o_keys.length;
		var o_current = 0;
		while(o_current < o_length) {
			var o = o_keys[o_current++];
			this.removeOverlay(o,true);
		}
		this._bloverlays = null;
		this._bloverlay.removeChildren();
		this._bloverlay = null;
		var h = this._instances.h;
		var i_h = h;
		var i_keys = Object.keys(h);
		var i_length = i_keys.length;
		var i_current = 0;
		while(i_current < i_length) {
			var i = i_keys[i_current++];
			this._instances.h[i].kill();
			var _this = this._instances;
			if(Object.prototype.hasOwnProperty.call(_this.h,i)) {
				delete(_this.h[i]);
			}
		}
		this._instances = null;
		this._uiArea.removeChildren();
		this._uiArea = null;
		this._uiBg.get_graphics().clear();
		this._uiBg = null;
		this._inputPanel.kill();
		this._inputPanel = null;
	}
	,clear: function() {
		motion_Actuate.stop(this,{ kfPercent : 100},false,false);
		this._currentKf = 0;
		this._scene.removeChildren();
		var h = this._instances.h;
		var i_h = h;
		var i_keys = Object.keys(h);
		var i_length = i_keys.length;
		var i_current = 0;
		while(i_current < i_length) {
			var i = i_keys[i_current++];
			this._instances.h[i].kill();
			var _this = this._instances;
			if(Object.prototype.hasOwnProperty.call(_this.h,i)) {
				delete(_this.h[i]);
			}
		}
		this._uiBg.set_visible(false);
		this._inputPanel.set_visible(false);
	}
	,setArea: function() {
		this._bg.get_graphics().clear();
		this._mask.get_graphics().clear();
		this._bg.get_graphics().beginFill(com_tilbuci_data_GlobalPlayer.movie.data.screen.bgcolor);
		this._mask.get_graphics().beginFill(0);
		if(com_tilbuci_data_GlobalPlayer.movie.data.screen.type == "square") {
			this._bg.get_graphics().drawRect(0,0,com_tilbuci_data_GlobalPlayer.movie.data.screen.big,com_tilbuci_data_GlobalPlayer.movie.data.screen.big);
			this._mask.get_graphics().drawRect(0,0,com_tilbuci_data_GlobalPlayer.movie.data.screen.big,com_tilbuci_data_GlobalPlayer.movie.data.screen.big);
		} else if(com_tilbuci_data_GlobalPlayer.movie.data.screen.type == "horizontal" || com_tilbuci_data_GlobalPlayer.movie.data.screen.type == "landscape") {
			this._bg.get_graphics().drawRect(0,0,com_tilbuci_data_GlobalPlayer.movie.data.screen.big,com_tilbuci_data_GlobalPlayer.movie.data.screen.small);
			this._mask.get_graphics().drawRect(0,0,com_tilbuci_data_GlobalPlayer.movie.data.screen.big,com_tilbuci_data_GlobalPlayer.movie.data.screen.small);
		} else if(com_tilbuci_data_GlobalPlayer.movie.data.screen.type == "vertical" || com_tilbuci_data_GlobalPlayer.movie.data.screen.type == "portrait") {
			this._bg.get_graphics().drawRect(0,0,com_tilbuci_data_GlobalPlayer.movie.data.screen.small,com_tilbuci_data_GlobalPlayer.movie.data.screen.big);
			this._mask.get_graphics().drawRect(0,0,com_tilbuci_data_GlobalPlayer.movie.data.screen.small,com_tilbuci_data_GlobalPlayer.movie.data.screen.big);
		} else if(this.get_pOrientation() == "vertical") {
			this._bg.get_graphics().drawRect(0,0,com_tilbuci_data_GlobalPlayer.movie.data.screen.small,com_tilbuci_data_GlobalPlayer.movie.data.screen.big);
			this._mask.get_graphics().drawRect(0,0,com_tilbuci_data_GlobalPlayer.movie.data.screen.small,com_tilbuci_data_GlobalPlayer.movie.data.screen.big);
		} else {
			this._bg.get_graphics().drawRect(0,0,com_tilbuci_data_GlobalPlayer.movie.data.screen.big,com_tilbuci_data_GlobalPlayer.movie.data.screen.small);
			this._mask.get_graphics().drawRect(0,0,com_tilbuci_data_GlobalPlayer.movie.data.screen.big,com_tilbuci_data_GlobalPlayer.movie.data.screen.small);
		}
		this._bg.get_graphics().endFill();
		this._mask.get_graphics().endFill();
		this._uiBg.set_width(this._mask.get_width() * this._scale);
		this._uiBg.set_height(this._mask.get_height() * this._scale);
		this._bgarea.get_graphics().clear();
		this._bgarea.get_graphics().beginFill(0);
		this._bgarea.get_graphics().drawRect(0,0,this._player.get_rWidth(),this._player.get_rHeight());
		this._bgarea.get_graphics().endFill();
		com_tilbuci_data_GlobalPlayer.contraptions.changeDisplay();
		this.place();
	}
	,showLoginInput: function(acOk,acCancel) {
		var logintitle = com_tilbuci_data_GlobalPlayer.parser.parseString("$_TEXTS:logintitle");
		if(logintitle == "") {
			logintitle = "Login";
		}
		var logintext = com_tilbuci_data_GlobalPlayer.parser.parseString("$_TEXTS:logintext");
		if(logintext == "") {
			logintext = "Please type your e-mail address. You'll receive a 6 digit code to confirm your identity.";
		}
		var termsagree = com_tilbuci_data_GlobalPlayer.parser.parseString("$_TEXTS:termsagree");
		if(termsagree == "") {
			termsagree = "I agree with the above terms.";
		}
		var invalidemail = com_tilbuci_data_GlobalPlayer.parser.parseString("$_TEXTS:invalidemail");
		if(invalidemail == "") {
			invalidemail = "Please provide a valid e-mail address.";
		}
		var emailwait = com_tilbuci_data_GlobalPlayer.parser.parseString("$_TEXTS:emailwait");
		if(emailwait == "") {
			emailwait = "Please wait while a confirmation code is sent to your e-mail.";
		}
		var noemailsent = com_tilbuci_data_GlobalPlayer.parser.parseString("$_TEXTS:noemailsent");
		if(noemailsent == "") {
			noemailsent = "Error while sending the code by e-mail. Please try again.";
		}
		var checkforcode = com_tilbuci_data_GlobalPlayer.parser.parseString("$_TEXTS:checkforcode");
		if(checkforcode == "") {
			checkforcode = "Please check out your e-mail inbox. Type below the 6 digit code you received. If you do not find the message, take a look at you spam folder.";
		}
		var codewait = com_tilbuci_data_GlobalPlayer.parser.parseString("$_TEXTS:codewait");
		if(codewait == "") {
			codewait = "Please wait while the provided code is checked.";
		}
		var invalidcode = com_tilbuci_data_GlobalPlayer.parser.parseString("$_TEXTS:invalidcode");
		if(invalidcode == "") {
			invalidcode = "The provided code is invalid. Please try again.";
		}
		var emailsubject = com_tilbuci_data_GlobalPlayer.parser.parseString("$_TEXTS:emailsubject");
		if(emailsubject == "") {
			emailsubject = "TilBuci login";
		}
		var emailbody = com_tilbuci_data_GlobalPlayer.parser.parseString("$_TEXTS:emailbody");
		if(emailbody == "") {
			emailbody = "Hi, you are receiving this message to confirm your login at TilBuci. Please provide the code below to proceed:\r\n\r\n[CODE]\r\n\r\nIf you did'nt request this code, don't worry: just ignore this message.";
		}
		var emailsender = com_tilbuci_data_GlobalPlayer.parser.parseString("$_TEXTS:emailsender");
		if(emailsender == "") {
			emailsender = "TilBuci";
		}
		this._inputPanel.askLogin(logintitle,logintext,termsagree,invalidemail,emailwait,noemailsent,checkforcode,codewait,invalidcode,emailsubject,emailbody,emailsender,acOk,acCancel);
	}
