	,checkJoystick: function(code) {
		var found = false;
		switch(code) {
		case "0":
			if(com_tilbuci_data_GlobalPlayer.usingTarget > 0) {
				com_tilbuci_data_GlobalPlayer.area.triggerTarget();
				found = true;
			} else {
				found = this.runInput("keyspace");
			}
			break;
		case "1":
			found = this.runInput("keyenter");
			break;
		case "2":
			found = this.runInput("keypup");
			break;
		case "3":
			found = this.runInput("keypdown");
			break;
		case "d":
			if(com_tilbuci_data_GlobalPlayer.usingTarget > 0) {
				com_tilbuci_data_GlobalPlayer.area.moveTarget("down");
				found = true;
			} else {
				found = this.runInput("keydown");
			}
			break;
		case "l":
			if(com_tilbuci_data_GlobalPlayer.usingTarget > 0) {
				com_tilbuci_data_GlobalPlayer.area.moveTarget("left");
				found = true;
			} else {
				found = this.runInput("keyleft");
			}
			break;
		case "r":
			if(com_tilbuci_data_GlobalPlayer.usingTarget > 0) {
				com_tilbuci_data_GlobalPlayer.area.moveTarget("right");
				found = true;
			} else {
				found = this.runInput("keyright");
			}
			break;
		case "u":
			if(com_tilbuci_data_GlobalPlayer.usingTarget > 0) {
				com_tilbuci_data_GlobalPlayer.area.moveTarget("up");
				found = true;
			} else {
				found = this.runInput("keyup");
			}
			break;
		}
		return found;
	}
