	,addContr: function(evt) {
		if(this.ui.inputs.h["name"].get_text().length > 3) {
			var okbt = true;
			var list = [];
			var el = this.ui.lists.h["elements"].get_dataProvider().iterator();
			while(el.hasNext()) {
				var el1 = el.next();
				switch(el1.value.type) {
				case "background":
					list.push(el1.value);
					break;
				case "btcancel":
					list.push(el1.value);
					break;
				case "btok":
					list.push(el1.value);
					if(el1.value.file == "") {
						okbt = false;
					}
					break;
				default:
					if(el1.value.name != "") {
						list.push(el1.value);
					}
				}
			}
			if(okbt) {
				if(list.length <= 3) {
					com_tilbuci_data_Global.showPopup(com_tilbuci_data_Global.ln.get("window-contrform-title"),com_tilbuci_data_Global.ln.get("window-contrform-noelem"),320,150,com_tilbuci_data_Global.ln.get("default-ok"));
				} else {
					var contr;
					var this1 = this._list;
					var key = this.ui.inputs.h["name"].get_text();
					if(Object.prototype.hasOwnProperty.call(this1.h,key)) {
						var this1 = this._list;
						var key = this.ui.inputs.h["name"].get_text();
						contr = this1.h[key];
					} else {
						contr = new com_tilbuci_contraptions_FormContraption();
					}
					if(contr.load({ id : this.ui.inputs.h["name"].get_text(), elem : list})) {
						var this1 = this._list;
						var k = this.ui.inputs.h["name"].get_text();
						this1.h[k] = contr;
						this.ui.inputs.h["name"].set_text("");
						this.clear();
					}
				}
			} else {
				com_tilbuci_data_Global.showPopup(com_tilbuci_data_Global.ln.get("window-contrform-title"),com_tilbuci_data_Global.ln.get("window-contrform-nook"),320,150,com_tilbuci_data_Global.ln.get("default-ok"));
			}
		} else {
			com_tilbuci_data_Global.showPopup(com_tilbuci_data_Global.ln.get("window-contrform-title"),com_tilbuci_data_Global.ln.get("window-contrform-noname"),320,150,com_tilbuci_data_Global.ln.get("default-ok"));
		}
	}
