						var tmp = this.ui.lists.h["elements"];
						var tmp1 = this.ui.numerics.h["formelposx"].get_value();
						tmp.get_selectedItem().value.x = Math.round(tmp1);
						var tmp = this.ui.lists.h["elements"];
						var tmp1 = this.ui.numerics.h["formelposy"].get_value();
