	,restrictValue: function(value) {
		if(this._snapInterval != 0.0 && value != this._minimum && value != this._maximum) {
			value = feathers_utils_MathUtil.roundToNearest(value,this._snapInterval);
		}
		if(value < this._minimum) {
			value = this._minimum;
		} else if(value > this._maximum) {
			value = this._maximum;
		}
		return value;
	}
	,decrement: function() {
		var newValue = this._value - this._step;
		newValue = this.restrictValue(newValue);
		this.set_value(newValue);
	}
	,increment: function() {
		var newValue = this._value + this._step;
		newValue = this.restrictValue(newValue);
		this.set_value(newValue);
	}
	,numericStepper_focusInHandler: function(event) {
		if(this.stage != null && this.stage.get_focus() != null && this.textInput != null && !this.textInput.contains(this.stage.get_focus())) {
			event.stopImmediatePropagation();
			this.stage.set_focus(this.textInput);
		}
	}
	,canKeyCodeUpdateValue: function(keyCode) {
		if(!(keyCode == 38 || keyCode == 40 || keyCode == 36)) {
			return keyCode == 35;
		} else {
			return true;
		}
	}
	,updateValueWithKeyboard: function(event) {
		if(event.isDefaultPrevented()) {
			return;
		}
		if(!this._enabled || !this.canKeyCodeUpdateValue(event.keyCode)) {
			return;
		}
		this.parseTextInputValue();
		var newValue = this._value;
		switch(event.keyCode) {
		case 35:
			newValue = this._maximum;
			break;
		case 36:
			newValue = this._minimum;
			break;
		case 38:
			newValue += this._step;
			break;
		case 40:
			newValue -= this._step;
			break;
		default:
			return;
		}
		if(newValue < this._minimum) {
			newValue = this._minimum;
		} else if(newValue > this._maximum) {
			newValue = this._maximum;
		}
		event.preventDefault();
		this.set_value(newValue);
		if(this.textInput.get_selectionActiveIndex() != this.textInput.get_selectionAnchorIndex()) {
			this.textInput.selectRange(this.textInput.get_selectionAnchorIndex(),this.textInput.get_selectionAnchorIndex());
		}
	}
	,numericStepper_decrementButton_mouseDownHandler: function(event) {
		if(!this._enabled || !this.decrementButton.get_enabled() || this.stage == null) {
			return;
		}
		var exclusivePointer = feathers_utils_ExclusivePointer.forStage(this.stage);
		var result = exclusivePointer.claimMouse(this);
		if(!result) {
			return;
		}
		this.decrement();
	}
	,numericStepper_decrementButton_touchBeginHandler: function(event) {
		if(event.isPrimaryTouchPoint) {
			return;
		}
		if(!this._enabled || !this.decrementButton.get_enabled() || this.stage == null) {
			return;
		}
		var exclusivePointer = feathers_utils_ExclusivePointer.forStage(this.stage);
		var result = exclusivePointer.claimMouse(this);
		if(!result) {
			return;
		}
		this.decrement();
	}
	,numericStepper_incrementButton_mouseDownHandler: function(event) {
		if(!this._enabled || !this.incrementButton.get_enabled() || this.stage == null) {
			return;
		}
		var exclusivePointer = feathers_utils_ExclusivePointer.forStage(this.stage);
		var result = exclusivePointer.claimMouse(this);
		if(!result) {
			return;
		}
		this.increment();
	}
	,numericStepper_incrementButton_touchBeginHandler: function(event) {
		if(event.isPrimaryTouchPoint) {
			return;
		}
		if(!this._enabled || !this.incrementButton.get_enabled() || this.stage == null) {
			return;
		}
		var exclusivePointer = feathers_utils_ExclusivePointer.forStage(this.stage);
		var result = exclusivePointer.claimMouse(this);
		if(!result) {
			return;
		}
		this.increment();
	}
	,numericStepper_textInput_keyDownHandler: function(event) {
		if(!this._enabled || event.isDefaultPrevented()) {
			return;
		}
		if(event.keyCode == 13) {
			event.preventDefault();
			this.parseTextInputValue();
			return;
		} else {
			this.updateValueWithKeyboard(event);
		}
	}
	,numericStepper_textInput_focusInHandler: function(event) {
		this._pendingTextInputChanges = false;
	}
	,numericStepper_textInput_changeHandler: function(event) {
		this._pendingTextInputChanges = true;
	}
	,numericStepper_textInput_focusOutHandler: function(event) {
		if(!this._pendingTextInputChanges) {
			return;
		}
		this.parseTextInputValue();
	}
