feathers_themes_steel_components_SteelDatePickerStyles.drawDecrementMonthIcon = function(icon,color) {
	icon.get_graphics().beginFill(16711935,0.0);
	icon.get_graphics().drawRect(0.0,0.0,8.0,8.0);
	icon.get_graphics().endFill();
	icon.get_graphics().beginFill(color);
	icon.get_graphics().moveTo(2.0,4.0);
	icon.get_graphics().lineTo(6.0,0.0);
	icon.get_graphics().lineTo(6.0,8.0);
	icon.get_graphics().lineTo(2.0,4.0);
	icon.get_graphics().endFill();
};
