feathers_themes_steel_components_SteelHierarchicalItemRendererStyles.drawDisclosureClosedIcon = function(icon,color,isDesktop) {
	icon.get_graphics().beginFill(16711935,0.0);
	if(isDesktop) {
		icon.get_graphics().drawRect(0.0,0.0,16.0,16.0);
	} else {
		icon.get_graphics().drawRect(0.0,0.0,20.0,20.0);
	}
	icon.get_graphics().endFill();
	icon.get_graphics().beginFill(color);
	if(isDesktop) {
		icon.get_graphics().moveTo(4.0,4.0);
		icon.get_graphics().lineTo(12.0,8.0);
		icon.get_graphics().lineTo(4.0,12.0);
		icon.get_graphics().lineTo(4.0,4.0);
	} else {
		icon.get_graphics().moveTo(4.0,4.0);
		icon.get_graphics().lineTo(16.0,10.0);
		icon.get_graphics().lineTo(4.0,16.0);
		icon.get_graphics().lineTo(4.0,4.0);
	}
	icon.get_graphics().endFill();
};
