feathers_themes_steel_components_SteelPopUpDatePickerStyles.drawIcon = function(icon,iconColor) {
	icon.get_graphics().lineStyle(1.0,iconColor);
	icon.get_graphics().drawRect(0.5,1.5,11.0,10.0);
	icon.get_graphics().moveTo(3.0,0.5);
	icon.get_graphics().lineTo(3.0,1.5);
	icon.get_graphics().moveTo(9.0,0.5);
	icon.get_graphics().lineTo(9.0,1.5);
	icon.get_graphics().lineStyle();
	icon.get_graphics().beginFill(iconColor);
	icon.get_graphics().drawRect(1.0,2.0,11.0,2.0);
	icon.get_graphics().drawRect(2.0,5.0,2.0,2.0);
	icon.get_graphics().drawRect(5.0,5.0,2.0,2.0);
	icon.get_graphics().drawRect(8.0,5.0,2.0,2.0);
	icon.get_graphics().drawRect(2.0,8.0,2.0,2.0);
	icon.get_graphics().drawRect(5.0,8.0,2.0,2.0);
	icon.get_graphics().drawRect(8.0,8.0,2.0,2.0);
	icon.get_graphics().endFill();
};
